-static inst* block_take_last(block* b) {
-  inst* i = b->last;
-  if (i == 0)
-    return 0;
-  if (i->prev) {
-    i->prev->next = i->next;
-    b->last = i->prev;
-    i->prev = 0;
-  } else {
-    b->first = 0;
-    b->last = 0;
-  }
-  return i;
