-block gen_const_object(block expr) {
-  int is_const = 1;
-  jv o = jv_object();
-  jv k = jv_null();
-  jv v = jv_null();
-  for (inst *i = expr.first; i; i = i->next) {
-    if (i->op == PUSHK_UNDER) {
-      k = jv_copy(i->imm.constant);
-      i = i->next;
-    } else if (i->op != SUBEXP_BEGIN ||
-        i->next == NULL ||
-        i->next->op != LOADK ||
-        i->next->next == NULL ||
-        i->next->next->op != SUBEXP_END) {
-      is_const = 0;
-      break;
-    } else {
-      k = jv_copy(i->next->imm.constant);
-      i = i->next->next->next;
-    }
-    if (i != NULL && i->op == PUSHK_UNDER) {
-      v = jv_copy(i->imm.constant);
-      i = i->next;
-    } else if (i == NULL ||
-        i->op != SUBEXP_BEGIN ||
-        i->next == NULL ||
-        i->next->op != LOADK ||
-        i->next->next == NULL ||
-        i->next->next->op != SUBEXP_END) {
-      is_const = 0;
-      break;
-    } else {
-      v = jv_copy(i->next->imm.constant);
-      i = i->next->next->next;
-    }
-    if (i == NULL || i->op != INSERT) {
-      is_const = 0;
-      break;
-    }
-    if (jv_get_kind(k) != JV_KIND_STRING) {
-      is_const = 0;
-      break;
-    }
-    o = jv_object_set(o, k, v);
-    k = jv_null();
-    v = jv_null();
-  }
-  if (!is_const) {
-    jv_free(o);
-    jv_free(k);
-    jv_free(v);
